sys_script.script:
(function executeRule(current, previous /*null when async*/) {
  try {
    var oldSt = previous ? (previous.application_status.getDisplayValue() || previous.getValue('application_status') || 'New') : 'New';
    var newSt = current.application_status.getDisplayValue() || current.getValue('application_status');
    var user = gs.getUserDisplayName() || gs.getUserName() || 'System';
    var nowStr = new GlideDateTime().getDisplayValue();
    var logEntry = '[' + nowStr + '] Status: ' + oldSt + ' -> ' + newSt + ' (By ' + user + ')';

    var existingRemarks = current.getValue('admin_remarks') || '';
    if (existingRemarks) {
      current.admin_remarks = logEntry + '\n' + existingRemarks;
    } else {
      current.admin_remarks = logEntry;
    }
  } catch(e) {
    gs.warn('Status history tracking error: ' + e.message);
  }
})(current, previous);
